const makeDrill = (key, name, phase, instructions, cue, aiProfile = 'combo') => ({
  key,
  name,
  phase,
  category: 'Ball Handling',
  instructions,
  cue,
  aiProfile,
  metricType: 'reps',
  metricLabel: 'Quality reps or full sequences',
});

function createProgram(config) {
  const cycleSeconds = config.workSeconds + config.resetSeconds;
  return {
    ...config,
    whyItMatters: config.whyItMatters ?? config.outcome,
    goal: config.goal ?? 'game-ready',
    totalDurationSeconds: config.drills.length * cycleSeconds,
    drills: config.drills.map((drill, index) => ({
      ...drill,
      durationSeconds: config.workSeconds,
      transitionSeconds: config.resetSeconds,
      duration: `${config.workSeconds} sec work · ${config.resetSeconds} sec reset`,
      difficulty: config.level,
      order: index + 1,
    })),
  };
}

