export const WORKOUT_PROGRAMS = [...TEN_MINUTE_PROGRAMS, ...TWENTY_MINUTE_PROGRAMS];

export function getWorkoutProgram(workoutKey) {
  return WORKOUT_PROGRAMS.find((program) => program.key === workoutKey) ?? null;
}
